style.css:
@-moz-document domain("roblox.com") {
/* ===== COLORES ===== */
:root {
    --rei-bg: #eef5fb;
    --rei-bg2: #dce7f3;
    --rei-card: rgba(255,255,255,0.85);
    --rei-blue: #9fbfdc;
    --rei-dark: #5e738d;
    --rei-red: #c94747;
    --rei-text: #33404f;
}

/* ===== FONDO GENERAL ===== */
body {
    background:
        linear-gradient(180deg,
        var(--rei-bg) 0%,
        var(--rei-bg2) 100%) !important;
    color: var(--rei-text) !important;
}

/* Fondo opcional */
body::before {
    content: "";
    position: fixed;
    inset: 0;
    background:
        radial-gradient(circle at top right,
        rgba(159,191,220,.35),
        transparent 40%);
    pointer-events: none;
    z-index: -1;
}

/* ===== BARRA SUPERIOR ===== */
.navbar,
.rbx-header,
#navigation-container {
    background: rgba(255,255,255,0.92) !important;
    border-bottom: 2px solid var(--rei-blue) !important;
    backdrop-filter: blur(8px);
}

/* ===== TARJETAS ===== */
.card,
.game-card-container,
.section-content,
.content {
    background: var(--rei-card) !important;
    border: 1px solid rgba(159,191,220,.5) !important;
    border-radius: 18px !important;
    box-shadow: 0 6px 20px rgba(80,100,120,.12);
}

/* ===== EFECTO HOVER ===== */
.card:hover,
.game-card-container:hover {
    transform: translateY(-3px);
    box-shadow: 0 10px 25px rgba(159,191,220,.35);
}

/* ===== BOTONES ===== */
.btn-primary,
.btn-secondary,
.btn-control-md {
    background: var(--rei-blue) !important;
    border: none !important;
    color: white !important;
    border-radius: 12px !important;
    transition: .3s;
}

.btn-primary:hover,
.btn-secondary:hover,
.btn-control-md:hover {
    background: var(--rei-dark) !important;
}

/* ===== ENLACES ===== */
a {
    color: var(--rei-dark) !important;
}

a:hover {
    color: var(--rei-red) !important;
}

/* ===== INPUTS ===== */
input,
textarea {
    background: rgba(255,255,255,.8) !important;
    color: var(--rei-text) !important;
    border: 1px solid var(--rei-blue) !important;
    border-radius: 10px !important;
}

/* ===== SCROLLBAR ===== */
::-webkit-scrollbar {
    width: 10px;
}

::-webkit-scrollbar-track {
    background: #edf3f9;
}

::-webkit-scrollbar-thumb {
    background: var(--rei-blue);
    border-radius: 20px;
}

::-webkit-scrollbar-thumb:hover {
    background: var(--rei-dark);
}

/* ===== PEQUEÑOS DETALLES ROJOS ===== */
.notification,
.text-error,
.text-danger {
    color: var(--rei-red) !important;
}

/* ===== IMAGEN DE FONDO ===== */
body::after {
    content: "";
    position: fixed;
    inset: 0;
    background: url(https://i.pinimg.com/736x/6e/bb/d4/6ebbd4776d5ce652f5ca9557230889dc.jpg);
    background-size: cover;
    background-position: center;
    opacity: 0.10;
    pointer-events: none;
    z-index: -2;
}
}
